using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "SafeguardEffect", menuName = "Data/Battle/Effects/Safeguard Effect")]
public class SafeguardEffect : Effect
{
	[SerializeField]
	private DefaultEffectAction effectAction;

	[SerializeField]
	private bool unholyMist;

	public override string GetEffectDescription(int amount, GameObject effectOwner)
	{
		string firstArgument = (unholyMist ? base.localizationManager.GetLocalizedAtTheEndOfItsTurn() : base.localizationManager.GetLocalizedAtTheStartOfYourTurn());
		string localizedEffectOwnerReceiveEffectFormatted = base.localizationManager.GetLocalizedEffectOwnerReceiveEffectFormatted(effectAction.Effect, amount);
		return base.localizationManager.GetLocalizedConditionActivationThenDecreaseFormatFormatted(firstArgument, localizedEffectOwnerReceiveEffectFormatted.RemoveLast(), this, 1);
	}

	public override int ActivateEffect(int amount, GameObject effectOwner)
	{
		ApplyArmor(effectOwner, amount);
		amount--;
		return amount;
	}

	private void ApplyArmor(GameObject effectOwner, int amount)
	{
		effectAction.CastTargetAmount(effectOwner, amount, null);
	}
}
